    if (fwrite(buffer, 1, SECTOR_SIZE, fp) != SECTOR_SIZE) {
        printf("Error writing to MBR file\n");
        fclose(fp);
        return 1;
    }

    fclose(fp);

    printf("Boot sector written to MBR successfully\n");

    return 0;
